from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import goodwill_credit
from ledgerly.errors import BillingError
from ledgerly.models import Invoice, LineItem

def inv(status="issued", price="50.00"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal(price))],status=status)

# basic
r = goodwill_credit(inv(), Decimal("5.00"), "late")
print("basic", r)
# zero/negative
for a in ["0.00","-1.00"]:
    try: goodwill_credit(inv(), a, "x")
    except BillingError as e: print("bad amount", a, e.code)
# exceeds
try: goodwill_credit(inv(), "50.01", "x")
except BillingError as e: print("exceeds", e.code)
# not issued
try: goodwill_credit(inv("draft"), "1.00", "x")
except BillingError as e: print("state", e.code)
# approval threshold 1000
big = inv(price="2000.00")
try: goodwill_credit(big, "1000.01", "x")
except BillingError as e: print("approval", e.code)
print("at threshold", goodwill_credit(big, "1000.00", "x")["amount"])
print("approved", goodwill_credit(big, "1000.01", "x", approved_by="mgr")["amount"])
# idempotency
audit.clear()
a = goodwill_credit(inv(), "5.00", "x", idempotency_key="k1")
b = goodwill_credit(inv(), "5.00", "x", idempotency_key="k1")
print("idem", a==b, len(audit.events("goodwill_credit")))
# rounding half-even
print("round", goodwill_credit(inv(), "5.005", "x")["amount"])
EOF"}

